-- V15_X - ED-46 (Catalogo completo de relatorios).
-- *** NUMERACAO PENDENTE - NAO INVENTADA ***
-- O plano v3.0, secao 3, reserva para a faixa reporting apenas numeros
-- nominais V15_1 (P3.22) e V15_2 (P3.41); para ED-46..ED-49 a faixa e
-- coletiva ("V15_x") e a regra da trilha de editais diz que a faixa so
-- vale como numero se alguma tabela precisar entrar antes da P3.12,
-- com sequencia global a partir de V100 e o modulo no nome. NENHUM
-- numero nominal foi reservado a ED-46: este DDL esta PRONTO e aguarda
-- a atribuicao do numero na integracao (sugestao a confirmar pelo dono
-- da integracao: proximo slot livre da faixa ou V100+, nunca assumir).
-- Renomear o arquivo para V<numero>__ed46_complete_catalog.sql ao integrar.
--
-- Conteudo:
--   * report_catalog_entries: o catalogo completo (196 itens) como dado
--     de produto consultavel - uma linha por relatorio das secoes 19
--     (VISAN) e 2.28 (SAMAE), item da 23d §5.2 ou item de POC, com a
--     dependencia textual da fonte e o status honesto. Espelho da
--     classe CompleteReportCatalog (gerada); o teste de consistencia
--     confere os dois lados. Sem tenant_id: e catalogo de produto,
--     como as linhas de fabrica de report_definitions (tenant_id NULL);
--     por isso NAO usa register_tenant_table (mesma justificativa da
--     V15_1 para report_definitions).
--   * 5 views novas (RPT-101..RPT-105) sobre fontes REAIS ja entregues:
--     service_protocols (V8_1/P1.36), cutoff_compensations (V9_2/P3.4),
--     meter_readings (V5_1/P2.7) e personal_data_access_log (V1_6).
--     security_invoker = true, como na V15_1, para a RLS valer pela view.
--   * Seed das 5 definicoes em report_definitions, no padrao da V15_1.
--
-- O que esta migration NAO faz (por desenho, ver RELATORIO-ED-46):
--   * nenhuma view para relatorio cuja fonte nao foi entregue
--     (ED-58 almoxarifado, P4.1 parcelamentos, ED-18 coletor, identidade
--     para acessos): eles existem SO como linhas do catalogo com a
--     dependencia nomeada;
--   * nenhum valor regulatorio (prazo, percentual, formula de agencia):
--     relatorio le o calculo persistido pela tarefa-fonte.

CREATE TABLE IF NOT EXISTS report_catalog_entries (
    id VARCHAR(80) PRIMARY KEY,
    edital_refs VARCHAR(200) NOT NULL,
    title VARCHAR(500) NOT NULL,
    source_ref VARCHAR(500) NOT NULL,
    status VARCHAR(30) NOT NULL
        CHECK (status IN ('EXECUTABLE', 'DELIVERED_P322', 'DELIVERED_BY_SOURCE_TASK',
                          'DEPENDENT_SOURCE', 'EXCLUDED_OWN_SOURCE')),
    report_code VARCHAR(10),
    view_name VARCHAR(80),
    poc_ref VARCHAR(10),
    note VARCHAR(1000)
);
CREATE INDEX IF NOT EXISTS idx_report_catalog_status
    ON report_catalog_entries(status);

-- =======================================================================
-- RPT-101 Produtividade por atendente (23d §5.2) - fonte: V8_1 (P1.36).
-- "Atendente" = created_by do protocolo: a V8_1 nao tem atribuicao
-- (handler) nem marcador de reabertura - atribuicao e da ED-35. A
-- metrica de reabertura fica FORA da view, declarada no catalogo, em
-- vez de um numero inventado a partir de transicao de status.
-- Tempo medio = media de (closed_at - created_at) dos encerrados.
-- =======================================================================
CREATE OR REPLACE VIEW rpt_produtividade_atendente WITH (security_invoker = true) AS
SELECT p.tenant_id,
       p.created_by AS atendente_id,
       COUNT(*) AS protocolos,
       COUNT(*) FILTER (WHERE p.status = 'CLOSED') AS encerrados,
       COUNT(*) FILTER (WHERE p.status NOT IN ('CLOSED', 'CANCELLED')) AS abertos,
       COUNT(*) FILTER (WHERE p.status = 'CLOSED' AND p.closed_at::date <= p.current_due_date) AS encerrados_no_prazo,
       ROUND(AVG(CASE WHEN p.status = 'CLOSED' AND p.closed_at IS NOT NULL
                      THEN EXTRACT(EPOCH FROM (p.closed_at - p.created_at)) / 3600.0 END)::numeric, 2) AS tempo_medio_horas
FROM service_protocols p
GROUP BY p.tenant_id, p.created_by;

-- =======================================================================
-- RPT-102 Reclamacoes por origem externa (23d §5.2) - fonte: V8_1.
-- Origem = canal do protocolo. Os canais externos de hoje sao REGULATOR
-- (agencia reguladora) e OMBUDSMAN (ouvidoria). A taxonomia completa da
-- ED-35 (Consumidor.gov.br, Procon/SINDEC, Ministerio Publico e
-- Defensoria, com prazo proprio em sac.external_channels) ainda NAO e
-- coluna da V8_1: quando a ED-35 a entregar, esta view passa a agrupar
-- pela nova dimensao. Ate la, agrupar por canal e a verdade disponivel -
-- a view NAO finge distinguir origens que a fonte nao distingue.
-- =======================================================================
CREATE OR REPLACE VIEW rpt_reclamacoes_origem_externa WITH (security_invoker = true) AS
SELECT p.tenant_id,
       p.channel AS origem,
       COUNT(*) AS protocolos,
       COUNT(*) FILTER (WHERE p.status = 'CLOSED') AS encerrados,
       COUNT(*) FILTER (WHERE p.status = 'CLOSED' AND p.closed_at::date > p.current_due_date) AS fora_do_prazo,
       ROUND(100.0 * COUNT(*) FILTER (WHERE p.status = 'CLOSED' AND p.closed_at::date > p.current_due_date)
             / NULLIF(COUNT(*) FILTER (WHERE p.status = 'CLOSED'), 0), 2) AS percentual_fora_do_prazo,
       ROUND(AVG(CASE WHEN p.status = 'CLOSED' AND p.closed_at IS NOT NULL
                      THEN EXTRACT(EPOCH FROM (p.closed_at - p.created_at)) / 3600.0 END)::numeric, 2) AS tempo_medio_horas
FROM service_protocols p
GROUP BY p.tenant_id, p.channel;

-- =======================================================================
-- RPT-103 Compensacoes pagas (TR-665/SG-891; 23d §5.2) - fonte: V9_2
-- (P3.4). Le o CALCULO PERSISTIDO (cutoff_compensations), nunca recalcula
-- formula de agencia: a formula aplicada (inclusive a de perfil da
-- P2.31) esta gravada na linha. So CREDITED (paga/creditada);
-- PENDING_BASIS nasce com credit_amount NULL por desenho da P3.4 e nao
-- e compensacao paga. A formula ARIS (RECONNECTION_4H_NO_CHARGE) credita
-- 0,00 com isencao da taxa: conta como compensacao de valor zero, que e
-- o efeito real dela - nao e erro de soma.
-- Tipos de compensacao existentes na fonte: UNDUE_CUT (corte indevido)
-- e LATE_RECONNECTION (atraso de religacao). Compensacao por interrupcao
-- ou por qualidade NAO tem calculo persistido na P3.4: sem linhas, sem
-- invencao (pendencia nomeada no relatorio da tarefa).
-- Tipo de usuario = categoria da subcategoria com MAIS economias da
-- unidade (desempate deterministico pelo codigo): interpretacao
-- declarada da ED-46, porque a unidade pode ter subcategorias em mais
-- de uma categoria (V3_1) e o edital nao define a atribuicao.
-- =======================================================================
CREATE OR REPLACE VIEW rpt_compensacoes_usuario WITH (security_invoker = true) AS
SELECT c.tenant_id,
       COALESCE((SELECT cat.code
                 FROM unit_subcategories us
                 JOIN subcategories sub ON sub.tenant_id = us.tenant_id AND sub.id = us.subcategory_id
                 JOIN categories cat ON cat.tenant_id = sub.tenant_id AND cat.id = sub.category_id
                 WHERE us.tenant_id = c.tenant_id AND us.unit_id = c.consumer_unit_id
                 ORDER BY us.economies DESC, cat.code ASC
                 LIMIT 1), 'SEM_CATEGORIA') AS tipo_usuario,
       c.trigger_reason AS tipo_compensacao,
       c.formula AS formula,
       COUNT(*) AS compensacoes,
       SUM(c.credit_amount) AS valor_total
FROM cutoff_compensations c
WHERE c.status = 'CREDITED'
GROUP BY c.tenant_id, tipo_usuario, c.trigger_reason, c.formula;

-- =======================================================================
-- RPT-104 Tempo entre leituras por leiturista (TR-199/SG-200 e
-- TR-795/SG-1022; POC-62) - fonte: V5_1 (P2.7): reader_id e captured_at
-- sao gravados na leitura. Intervalo = diferenca para a leitura anterior
-- do MESMO leiturista no MESMO dia (LAG); a primeira leitura do dia nao
-- tem intervalo e nao entra na media (AVG ignora NULL). Dia com uma so
-- leitura: tempo_total = 0 e intervalo NULL - ausencia explicita, nao
-- zero inventado.
-- =======================================================================
CREATE OR REPLACE VIEW rpt_tempo_entre_leituras_leiturista WITH (security_invoker = true) AS
SELECT s.tenant_id,
       s.reader_id AS leiturista_id,
       s.read_on AS data,
       COUNT(*) AS leituras,
       ROUND((EXTRACT(EPOCH FROM (MAX(s.captured_at) - MIN(s.captured_at))) / 3600.0)::numeric, 2) AS tempo_total_horas,
       ROUND(AVG(EXTRACT(EPOCH FROM (s.captured_at - s.anterior)))::numeric, 1) AS intervalo_medio_segundos
FROM (
    SELECT mr.tenant_id, mr.reader_id, mr.read_on, mr.captured_at,
           LAG(mr.captured_at) OVER (PARTITION BY mr.tenant_id, mr.reader_id, mr.read_on
                                     ORDER BY mr.captured_at) AS anterior
    FROM meter_readings mr
    WHERE mr.reader_id IS NOT NULL
) s
GROUP BY s.tenant_id, s.reader_id, s.read_on;

-- =======================================================================
-- RPT-105 Acessos a dados pessoais por usuario (23d §5.2) - fonte:
-- personal_data_access_log (V1_6, P0.11/P1.12). Uso de cotas aqui =
-- resultado QUOTA_EXCEEDED do log. Nenhum documento aparece: o log, por
-- desenho, nunca guarda documento em claro (so o indice cego), e esta
-- view nao expoe nem o indice.
-- =======================================================================
CREATE OR REPLACE VIEW rpt_acessos_dados_usuario WITH (security_invoker = true) AS
SELECT l.tenant_id,
       l.user_id AS usuario_id,
       COUNT(*) AS acessos,
       COUNT(*) FILTER (WHERE l.access_type = 'EXPORT') AS exportacoes,
       COUNT(*) FILTER (WHERE l.result = 'DENIED') AS negados,
       COUNT(*) FILTER (WHERE l.result = 'QUOTA_EXCEEDED') AS cotas_excedidas,
       MAX(l.accessed_at) AS ultimo_acesso
FROM personal_data_access_log l
GROUP BY l.tenant_id, l.user_id;

